// WebSocket client for Home Assistant state sync.
const ws = require('ws');
let socket = null;
let states = {};
const WS_PATH = '/api/websocket';
const READ_ONLY = ['sensor', 'binary_sensor', 'input_datetime', 'weather', 'zone', 'device_tracker'];

on('input', async (msg) => {
  if (!socket) { await startWS(); }
  const entity = msg.entityId || env.get('HA_ENTITY_ID');
  if (!entity) { node.status({fill:'red',text:'no entity'}); return null; }
  if (READ_ONLY.includes(msg.domain || 'light')) { node.status({fill:'red',text:'read-only'}); return null; }
  const url = \`${env.get('HA_URL').replace(/\/+$/, '')}/api/services/${msg.domain || 'homeassistant'}/${msg.service}\`;
  node.send({payload: {url, method: 'POST', body: {entity_id: entity, ...msg.serviceData}}, topic: 'ha/control'});
  return msg;
})

async function startWS() {
  const baseUrl = env.get('HA_URL') || 'http://homeassistant.local:8123';
  const token = env.get('HA_TOKEN');
  if (!token) { node.status({fill:'red',text:'no token'}); return; }
  const wsUrl = baseUrl.replace(/^http/, 'ws') + WS_PATH;
  socket = new ws(wsUrl);
  socket.on('open', () => { socket.send(JSON.stringify({type: 'auth', access_token: token})); });
  socket.on('message', (data) => {
    const m = JSON.parse(data);
    if (m.type === 'auth_required') { socket.send(JSON.stringify({type: 'auth', access_token: token})); }
    else if (m.type === 'auth_ok') {
      socket.send(JSON.stringify({type: 'get_states'}));
      socket.send(JSON.stringify({type: 'subscribe_events', event_type: 'state_changed'}));
    } else if (m.type === 'result' && m.success && Array.isArray(m.result)) {
      m.result.forEach(s => { if (s.entity_id) states[s.entity_id] = s; });
      node.send({payload: Object.keys(states).length, topic: 'ha/state_count'});
    } else if (m.type === 'event' && m.event && m.event.data) {
      const eid = m.event.data.entity_id;
      const ns = m.event.data.new_state;
      if (ns) {
        states[eid] = ns;
        const norm = {entityId: eid, domain: eid.split('.')[0], state: ns.state, friendlyName: ns.attributes.friendly_name || eid, isOn: ns.state === 'on', brightnessPct: ns.attributes.brightness_pct || null};
        node.send({payload: norm, topic: `ha/entity/${eid}/state`});
      }
    }
  });
  socket.on('close', () => { socket = null; });
  socket.on('error', (err) => { node.status({fill:'red',text:'WS error'}); });
}

// REST controller for Home Assistant service calls
on('input', async (msg) => {
  msg.headers = {'Authorization': 'Bearer ' + env.get('HA_TOKEN'), 'Content-Type': 'application/json'};
  msg.method = msg.method || 'POST';
  msg.url = msg.url.replace(/\/+$/, '');
  msg.payload = msg.body || {};
  msg.rejectUnauthorized = false;
  node.status({fill:'green',text:'sending to HA'});
  return msg;
})
